<script setup>
import {onMounted,ref} from 'vue';
import {LibraryBig,Plus,Download,Pencil,Send,Trash2,X,RefreshCw} from 'lucide-vue-next';
import MaterialForm from '~/components/tutor/MaterialForm.vue';
import {useAuthStore} from '~/stores/api/auth';
import {useTutorMaterialsStore} from '~/stores/api/tutorMaterials';
import {canAccessPage} from '~/utils/roles';
definePageMeta({layout:'default'});
const auth=useAuthStore(),store=useTutorMaterialsStore(),ready=ref(false),editing=ref(null),error=ref(''),notice=ref('');
async function refresh(){await store.fetchItems();}
async function save(form){error.value='';try{await store.save(editing.value.id,form);editing.value=null;notice.value='Materi berhasil diperbarui.';await refresh();}catch(e){error.value=e?.data?.message||'Gagal menyimpan materi.';}}
async function submit(item){error.value='';try{await store.submit(item.id);notice.value='Materi berhasil diterbitkan.';await refresh();}catch(e){error.value=e?.data?.message||'Gagal menerbitkan materi.';}}
async function remove(item){if(!confirm('Hapus materi draft ini?'))return;error.value='';try{await store.remove(item.id);notice.value='Materi berhasil dihapus.';await refresh();}catch(e){error.value=e?.data?.message||'Gagal menghapus materi.';}}
async function download(item){error.value='';try{await store.download(item);}catch(e){error.value=e.message;}}
onMounted(async()=>{auth.initializeAuth();if(!auth.token)return navigateTo('/login');const user=await auth.fetchCurrentUser();if(Number(user?.role)!==3||!canAccessPage(user?.role,'materials.own'))return navigateTo('/dashboard');ready.value=true;await refresh();});
</script>
<template><div v-if="ready" class="mx-auto w-full max-w-[1450px] min-w-0 px-4 py-5 sm:px-6 lg:px-8"><header class="mb-5 flex flex-wrap items-center justify-between gap-3"><div><h1 class="font-headline-md text-headline-md">Materi Saya</h1><p class="text-sm text-on-surface-variant">Kelola file materi yang kamu buat.</p></div><NuxtLink to="/my-materials/create" class="inline-flex items-center gap-2 rounded-2xl bg-primary-container px-4 py-2.5 text-sm text-white"><Plus class="h-4 w-4"/>Tambah Materi</NuxtLink></header><p v-if="error" role="alert" class="mb-4 rounded-2xl bg-danger-soft p-3 text-danger-rose">{{ error }}</p><p v-if="notice" role="status" class="mb-4 rounded-2xl bg-success-soft p-3 text-success-emerald">{{ notice }}</p><section class="rounded-3xl border border-soft-blue bg-surface-white p-4 shadow-sm sm:p-6"><div class="mb-4 flex items-center justify-between"><h2 class="font-title-md text-title-md">Daftar Materi</h2><button class="text-primary-container" aria-label="Muat ulang materi" @click="refresh"><RefreshCw class="h-4 w-4"/></button></div><div v-if="store.loading" class="space-y-3"><div v-for="n in 3" :key="n" class="h-24 animate-pulse rounded-2xl bg-surface-container"/></div><div v-else-if="!store.items.length" class="py-10 text-center"><LibraryBig class="mx-auto h-10 w-10 text-primary-container"/><p class="mt-3 font-semibold">Belum ada materi</p><p class="text-sm text-on-surface-variant">Mulai unggah materi pertamamu.</p></div><div v-else class="space-y-3"><article v-for="item in store.items" :key="item.id" class="rounded-2xl border border-soft-blue p-4"><div class="flex flex-wrap items-center gap-2"><h3 class="min-w-0 flex-1 font-semibold">{{ item.title }}</h3><span class="rounded-full px-2 py-1 text-xs" :class="item.status==='active'?'bg-success-soft text-success-emerald':'bg-surface-container text-outline'">{{ item.status==='active'?'Aktif':'Draft' }}</span></div><p class="mt-1 text-xs text-on-surface-variant">{{ item.subtest }} · {{ item.category }} · {{ item.file_name }}</p><p v-if="item.description" class="mt-2 line-clamp-2 text-sm text-on-surface-variant">{{ item.description }}</p><div class="mt-4 flex flex-wrap justify-end gap-2"><button class="inline-flex items-center gap-1 rounded-xl border border-soft-blue px-3 py-2 text-sm" @click="download(item)"><Download class="h-4 w-4"/>File</button><button v-if="item.status==='draft'" class="inline-flex items-center gap-1 rounded-xl border border-soft-blue px-3 py-2 text-sm" @click="editing=item"><Pencil class="h-4 w-4"/>Edit</button><button v-if="item.status==='draft'" class="inline-flex items-center gap-1 rounded-xl bg-primary-container px-3 py-2 text-sm text-white" @click="submit(item)"><Send class="h-4 w-4"/>Terbitkan</button><button v-if="item.status==='draft'" class="inline-flex items-center gap-1 rounded-xl border border-danger-rose px-3 py-2 text-sm text-danger-rose" @click="remove(item)"><Trash2 class="h-4 w-4"/>Hapus</button></div></article></div><div class="mt-4 flex justify-end gap-2 text-sm"><button :disabled="store.pagination.page<=1" class="rounded-xl border border-soft-blue px-3 py-2 disabled:opacity-40" @click="store.pagination.page--;refresh()">Sebelumnya</button><span class="px-2 py-2">{{ store.pagination.page }} / {{ store.pagination.total_pages }}</span><button :disabled="store.pagination.page>=store.pagination.total_pages" class="rounded-xl border border-soft-blue px-3 py-2 disabled:opacity-40" @click="store.pagination.page++;refresh()">Berikutnya</button></div></section><div v-if="editing" class="fixed inset-0 z-50 overflow-y-auto bg-black/50 p-4" @click.self="editing=null"><div class="mx-auto my-6 w-full max-w-3xl"><div class="mb-3 flex items-center justify-between rounded-2xl bg-surface-white p-4"><h2 class="font-title-md text-title-md">Edit Materi</h2><button aria-label="Tutup" @click="editing=null"><X class="h-5 w-5"/></button></div><MaterialForm :initial="editing" :saving="store.saving" @submit="save"/></div></div></div></template>
